-- Evaluation assets are private and are only served through short-lived URLs
-- generated by the service-role client used by the local review tooling.
INSERT INTO storage.buckets (
  id,
  name,
  public,
  file_size_limit,
  allowed_mime_types
)
VALUES (
  'image-eval',
  'image-eval',
  false,
  5242880,
  ARRAY['image/webp']
)
ON CONFLICT (id) DO UPDATE
SET public = false,
    file_size_limit = EXCLUDED.file_size_limit,
    allowed_mime_types = EXCLUDED.allowed_mime_types;

-- Deliberately no anon/authenticated policies. service_role bypasses storage
-- RLS for capture and signed-url generation.
